/**
 * Retrieve the current stage instructions for the LLM
 */
async function getFlowContext(intent, sessionData = {}, tenantId = 1) {
    const handler = FLOW_CONTEXTS[intent];
    if (!handler) return '';
    return await handler(sessionData, tenantId);
}

/**
 * Calculate and return a finance breakdown object (NCR-compliant)
 */
function buildFinanceBreakdown(price, deposit, ratePercent) {
    const rate = ratePercent || financeCalc.SA_RATES.defaultRate;
    const scenarios = [48, 60, 72].map(term => {
        const result = financeCalc.calculate({ vehiclePrice: price, deposit, termMonths: term, annualRate: rate });
        return {
            term_months: term,
            monthly: result.monthly.total,
            total_repayable: result.costOfCredit.totalRepayable,
            total_interest: result.costOfCredit.totalInterest,
            apr: result.apr,
        };
    });
    return { principal: price - deposit, deposit, rate, scenarios };
}

/**
 * Generate 3-scenario chatbot finance text
 */
function chatbotFinanceQuote(price, deposit, vehicleLabel, termMonths = 72) {
    return financeCalc.chatbotScenarios({
        vehiclePrice: price,
        deposit: deposit || 0,
        annualRate: financeCalc.SA_RATES.defaultRate,
        termMonths,
    }, vehicleLabel);
}

/**
 * Estimate trade-in value (simplified Kelley Blue Book-style model)
 * Returns a ZAR range — in production replace with actual market data API
 */
function estimateTradeIn({ year, make, model, mileage, condition }) {
    const currentYear = new Date().getFullYear();
    const age = currentYear - (year || currentYear);

    // Very rough depreciation model for illustration
    const BASE_VALUES = { new: 300000, demo: 250000, used: 200000 };
    let base = BASE_VALUES.used;
    const depreciation = 0.85 ** age;  // 15% per year compound
    const mileageFactor = Math.max(0.5, 1 - (mileage || 0) / 500000);
    const conditionMultiplier = { Excellent: 1.0, Good: 0.85, Fair: 0.7, Poor: 0.55 }[condition] || 0.75;

    const estimatedValue = Math.round(base * depreciation * mileageFactor * conditionMultiplier / 5000) * 5000;
    const low = Math.round(estimatedValue * 0.92);
    const high = Math.round(estimatedValue * 1.08);

    return { low, high, note: 'Subject to physical inspection by our appraiser.' };
}

module.exports = { getFlowContext, buildFinanceBreakdown, chatbotFinanceQuote, estimateTradeIn, FLOW_CONTEXTS };

